# su26-ext: showcase all 32 tiles from Super Mario Bros. NES tileset
#
# Art source (Spriters Resource asset 52571):
#   https://www.spriters-resource.com/nes/supermariobros/asset/52571/
#
# VRAM blobs are generated by tools/import_smb_tiles.py and baked into
# the binary by tools/build_all_tiles.py (copies at runtime from
# embedded data, or pre-filled by the build script).
#
# Layout (20×15 map) — filled by tools/import_smb_tiles.py:
#   Row 0:      decorative clouds
#   Rows 1–2:   catalog strip (tiles 0–31)
#   Rows 4–7:   4×8 gallery of all 32 tiles
#   Sides:      green pipes
#   Rows 13–14: ground strip
#   Fill:       solid sky (tile 0)
#
# Build:
#   python3 tools/build_all_tiles.py
# Run:
#   python3 -m machines.zx16sim --machine su26-ext bins/all_tiles.bin --gui

.text
.org 0x0020
main:
    # Enable display (CTRL = 1)
    li      t0, 0xE0
    slli    t0, 8
    li      t1, 1
    sb      t1, 0(t0)

    # VRAM is pre-filled by the build tool (palettes, 32 tiles, map, attr).
    # Optional runtime re-copy is not required for the hang demo.

hang:
    j       hang
